// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, bytes calldata data, address adr) public {
        vm.assume(amount > 0);
        vm.assume(adr != address(c));
        vm.assume(data.length <= 100);
        vm.deal(address(c), 0 ether);
        vm.deal(address(this), amount);
        uint256 beforeBal = adr.balance;
        c.Command{value: amount}(adr, data);
        uint256 afterBal = adr.balance;
        assertTrue(afterBal >= beforeBal + amount);
    }
}
